  "value.sustained",
] as const;
export type DashboardMetric = (typeof DASHBOARD_METRICS)[number];
export const dashboardMetric = z.enum(DASHBOARD_METRICS);

/** OpenAPI `FinanceValueClass` (ADR-0030 §7; ADR-0037 amendment K1): the class a value-state drill-down narrows to. */
export const FINANCE_VALUE_CLASSES = [
  "revenue_uplift",
  "margin_uplift",
  "cash_saving",
  "avoided_cost",
  "working_capital_release",
  "non_financial_valued",
] as const;
export type FinanceValueClass = (typeof FINANCE_VALUE_CLASSES)[number];
export const financeValueClass = z.enum(FINANCE_VALUE_CLASSES);

/**
 * OpenAPI `HeadlineBasis` (ADR-0030 and ADR-0037 amendment N3; D-119; M0172): the basis of a value headline.
 * profit_and_cash = margin_uplift + cash_saving + working_capital_release (the basis of the Finance gross); top_line =
 * revenue_uplift; non_cash = avoided_cost. Bases are never summed into each other.
 */
export const HEADLINE_BASES = ["profit_and_cash", "top_line", "non_cash"] as const;
export type HeadlineBasis = (typeof HEADLINE_BASES)[number];
export const headlineBasis = z.enum(HEADLINE_BASES);

/** The Finance classes of each headline basis (ADR-0037 amendment N3 items 1-2); non_financial_valued is in none. */
export const HEADLINE_BASIS_CLASSES: Readonly<Record<HeadlineBasis, readonly FinanceValueClass[]>> = Object.freeze({
  profit_and_cash: ["margin_uplift", "cash_saving", "working_capital_release"],
  top_line: ["revenue_uplift"],
  non_cash: ["avoided_cost"],
});

/** OpenAPI `DashboardValue.state` (ADR-0037 §5): value and zero are known; unknown and not_applicable carry no value. */
export const DASHBOARD_VALUE_STATES = ["value", "zero", "unknown", "stale", "not_applicable"] as const;
export type DashboardValueState = (typeof DASHBOARD_VALUE_STATES)[number];

// ------------------------------------------------------------------------------------------------ shapes

/**
 * OpenAPI `DashboardKpiUnit` (ADR-0037 amendment N5; D-124): the unit of a KPI-derived dashboard value. `kind` decides
 * the scaling exactly as the KPI pages' `formatKpiValue` (a `percentage` is a fraction × 100, ADR-0028 §3; a `ratio` a
 * plain decimal); `label` is display text only, the KPI's trimmed unit label or null.
 */
export const dashboardKpiUnit = z.strictObject({
  kind: kpiUnitKind,
  label: z.string().min(1).max(50).nullable(),
});
export type DashboardKpiUnit = z.infer<typeof dashboardKpiUnit>;

/**
 * OpenAPI `DashboardValue`. ADR-0037 amendment N5: `kpiUnit` is non-null exactly on a KPI-derived value; money (unit
 * `currency`), the computed ratio (unit `ratio`, the value gap, a percentage) and counts carry null. `kpiUnit` is
 * required: the API emits it (T-DG4-KBE-R8).
 */
/** OpenAPI `DashboardRag`. */
export const dashboardRag = z.strictObject({
  status: ragStatus,
  ruleKey: z.string(),
  ruleParams: z.record(z.string(), z.unknown()),
  policySource: z.enum(["default", "configured"]),
});
