  ordinal = 1,
): Promise<string> {
  const id = uuidv7();
  await api.db.transaction().execute(async (tx) => {
    const m = await scopeOf(tx, meetingId);
    await tx
      .insertInto("agenda_item")
      .values({
        id,
        organization_id: m.organization_id,
        transformation_id: m.transformation_id,
        meeting_id: meetingId,
        ordinal,
        item_kind: "discussion",
        title: "Synthetic agenda item",
        created_by: userId,
        updated_by: userId,
      })
      .execute();
    const scope = { organizationId: m.organization_id, transformationId: m.transformation_id };
    await insertAuditEvent(tx, actor(userId), {
      action: "agenda_item.create",
      recordType: "agenda_item",
      recordId: id,
      ...scope,
      newVersion: 1,
    });
    if (status === "published") {
      await tx
        .updateTable("agenda_item")
        .set({ status: "published", published_at: new Date(), published_by: userId, version: 2 })
        .where("id", "=", id)
        .execute();
      await insertAuditEvent(tx, actor(userId), {
        action: "agenda_item.publish",
        recordType: "agenda_item",
        recordId: id,
  w = await seedWorld(api.db);
  x = await setupMeetingWorld(api, w);
  today = await businessToday(api);
}, 120_000);
afterAll(() => api.close());

const T = () => `/api/v1/transformations/${x.transformationId}`;

/** An ad-hoc meeting of a forum (TL creates it; the chair comes from the forum's chair party). */
async function meeting(forum: ForumKey, days = 10): Promise<{ id: string; url: string; chair: string | null }> {
  const res = await send("POST", `${T()}/meetings`, {
