    expect(itemValueState(stale, "outcome_kpi")).toMatchObject({ validation: "stale", reason: "stale" });
    expect(itemReportValue(stale, "outcome_kpi")).toEqual({
      type: "decimal",
      value: null,
      unitKind: "percentage",
      currency: null,
      valueBasis: "actual",
      validation: "stale",
      reason: "stale",
    });
  });
