    const unknown = dv({ state: "unknown", value: null, reasonKey: "kpi.no_accepted_actual", kpiUnit: { kind: "ratio", label: null } });
    expect(itemReportValue(unknown, "outcome_kpi")).toMatchObject({ value: null, validation: "unknown", reason: "not_computable" });
