head='''// The export content label table (T-DG5-KBE-D2; D-157 a; p5-work-split §F.11 item 10; REQ-S13-009, REQ-S13-008;
// ADR-0045 §3 "labels are translated at render time"; ADR-0046 §2-§4).
//
// Every system label a report assembler puts in a document - section titles, field and column labels, code labels
// (`<prefix>.<value>` of a closed set) and empty-section texts - is an i18n key; this table holds its English and
// Arabic text. The production `reports.export` handler (apps/worker/src/handlers/reports.ts `exportRunnerDeps`) passes
// it to the renderers as `labels`, next to @mth/reporting's own frame labels, so an Arabic export prints Arabic content
// headings and an English one English headings: no key falls back to a key-derived English text (`missingLabels`).
// It lives in @mth/shared because the worker imports no API code (ADR-0002); the API's assemblers emit the keys.
//
// Sources of the texts: the bilingual catalogue seeds where they exist (gate criteria, diagnostic and TOM dimensions,
// diagnostic workstreams, Template 10 areas, roles: the migrations' label_en/label_ar), the web's dashboard headline
// labels (apps/web/src/i18n/{en,ar}/dashboards.json), and the texts below for every other key. User-authored text is
// never in this table: it is printed as authored. Product gates G1-G6 are business approvals inside the product; no
// label names an engineering delivery gate or claims any certification.
// Completeness is tested: every key the twelve assemblers emit renders without `missingLabels` in en and ar
// (apps/api/test/integration/reporting/export-labels.test.ts), and every closed set's values have a label
// (content-labels.test.ts).

/** key -> [English, Arabic]. Sorted by key. */
const PAIRS: Readonly<Record<string, readonly [en: string, ar: string]>> = {
'''
body=''.join(f'  {json.dumps(k)}: [{json.dumps(v[0],ensure_ascii=False)}, {json.dumps(v[1],ensure_ascii=False)}],\n' for k,v in sorted(p.items()))
tail='''};

export type ReportLabelLanguage = "en" | "ar";

/** The content label table by language (the shape of @mth/reporting's `LabelTable`). */
export const REPORT_CONTENT_LABELS: Readonly<Record<ReportLabelLanguage, Readonly<Record<string, string>>>> = Object.freeze({
  en: Object.freeze(Object.fromEntries(Object.entries(PAIRS).map(([k, [en]]) => [k, en]))),
  ar: Object.freeze(Object.fromEntries(Object.entries(PAIRS).map(([k, [, ar]]) => [k, ar]))),
});
'''
open('packages/shared/src/reports/content-labels.ts','w').write(head+body+tail)
EOF
